# Code generated by Claude
"""Arm targets of the test-only scripted grasp moves, computed by inverse kinematics from the beaker's position at the stance the robot stands in (David 2026-10-19).

Until now experiments/episode_test_sources.py took the grasp pose and its waypoint ("ready") from TASK_CFG's stored joint solutions (grasp_q, ready_q), which belong to the stance of an
older layout search: at any other stance they put the hand somewhere else. This module solves them for the stance the robot is actually at, when the stage takes its first step (the arms
are at home then, the base and the pedestal at the staging pose, the beaker on the bench).

    grasp_targets(model, data, side="left", frac=0.5) -> {"ready_q", "grasp_q", ...}

grasp_q: the pad centre (the centre of the finger pads' contact patch, src/gripper_geometry.py) on the beaker's axis at `frac` of its height above the bench top, as a grasp in the sense of
the reachability maps (src/grasp_rules.py: the hand's approach axis and finger-closing axis within level_deg of horizontal, the approach direction inside one of the 12 bins), found by the
same damped-least-squares solver as the maps (src/arm_kinematics.solve_ik with src/grasp_rules.make_constraint) from the home pose and random starts. A solution must keep the arm clear of
the robot's own parts (src/arm_collision.ArmCollisionChecker: the other arm as it is now, the torso, the pedestal at its current height, the base, the neck) and, with the fingers open, at
least `min_clear` from the bench, the hotplate and everything else in the scene except the beaker; of the solutions the one with the largest joint margin wins.
ready_q: the waypoint on the way from home, the pad centre 11.5 cm above the beaker's top and 5 cm back from the beaker towards the robot along the
grasp's approach direction (the legacy ready pose's rule, SEARCH_CFG), the solution closest to the grasp in joint space. The straight joint-space moves home -> ready -> grasp (what the
stages' minimum-jerk move does) are then checked at many points along them against the same two clearances; if no ready solution makes both segments clear, the function raises.

Contents:
    grasp_targets(model, data, side, frac, ...): see above.
"""

import math

import mujoco
import numpy as np

from src import robot_specs
from src.arm_collision import ArmCollisionChecker
from src.arm_kinematics import arm_chain, batch_fk, shoulder_origin, solve_ik
from src.grasp_rules import bin_center, joint_bounds, make_constraint
from src.gripper_geometry import grasp_cfg
from src.robot_helpers import arm_ids
from src.task_config import BEAKER_CFG, SEARCH_CFG, STAGING_CFG


class _World:
    """The arm's smallest distance to the scene (everything but the robot and the beaker), kinematics only, on a private copy of the state."""

    def __init__(self, model, data, side):
        self.m, self.side = model, side
        self.d = d = mujoco.MjData(model)
        d.qpos[:] = data.qpos
        for sd in ("left", "right"):
            for j in arm_ids(model, sd)["finger_jnt"]:
                d.qpos[model.jnt_qposadr[j]] = STAGING_CFG["finger_open"]
        root = model.body("base_link").id

        def under_root(b):
            while b > 0:
                if b == root:
                    return True
                b = int(model.body_parentid[b])
            return False

        bname = lambda g: model.body(int(model.geom_bodyid[g])).name
        self.arm = [g for g in range(model.ngeom) if model.geom_group[g] == 3 and bname(g).startswith(f"openarm_{side}_") and not bname(g).endswith("link0")]
        self.world = [g for g in range(model.ngeom) if (model.geom_contype[g] or model.geom_conaffinity[g]) and int(model.geom_type[g]) != int(mujoco.mjtGeom.mjGEOM_PLANE)
                      and not under_root(int(model.geom_bodyid[g])) and bname(g) != BEAKER_CFG["body"]]
        self.qadr = arm_ids(model, side)["qadr"]
        self.ft = np.zeros(6)

    def min_distance(self, q, look=0.1):
        """Smallest distance (metres, negative: penetration; `look` when nothing is closer) of any moving arm geom to the scene at the joint vector q."""
        m, d = self.m, self.d
        d.qpos[self.qadr] = q
        mujoco.mj_kinematics(m, d)
        best = look
        for a in self.arm:
            for b in self.world:
                if np.linalg.norm(d.geom_xpos[a] - d.geom_xpos[b]) - m.geom_rbound[a] - m.geom_rbound[b] > best:
                    continue
                best = min(best, mujoco.mj_geomDistance(m, d, a, b, look, self.ft))
        return float(best)


def _margin(model, side, Q):
    """Each row's distance of its closest joint to its limit, radians (Q: (N, 7))."""
    rng = model.jnt_range[arm_ids(model, side)["jnt"]]
    return np.minimum(Q - rng[:, 0], rng[:, 1] - Q).min(axis=1)


def _segment_clear(world, checker, a, b, min_clear, step_rad=math.radians(1.0)):
    """Whether the straight joint-space move a -> b stays clear: (ok, smallest distance to the scene, metres)."""
    n = max(2, int(np.ceil(np.abs(b - a).max() / step_rad)) + 1)
    Q = a + np.linspace(0.0, 1.0, n)[:, None] * (b - a)
    if checker.check(Q).any():
        return False, -1.0
    dmin = min(world.min_distance(q) for q in Q)
    return dmin >= min_clear, dmin


def grasp_targets(model, data, side="left", frac=0.5, n_seeds=300, seed=0, min_clear=0.005, ready_above_top=SEARCH_CFG["ready_clear_above_top"], ready_back=SEARCH_CFG["ready_back_off"]):
    """Solves the grasp pose and its waypoint for the beaker where it stands now, at the stance the robot is at now.

    Args:
        model (mujoco.MjModel): The compiled model (the robot and the scene with the beaker).
        data (mujoco.MjData): The simulation state: the base at its stance, the pedestal at its height, the arms where they are (the start of the move, normally home), the beaker placed.
            Read only.
        side (str): The arm, "left" or "right". Defaults to "left".
        frac (float): The grasp height as a fraction of the beaker's height above the bench top. Defaults to 0.5 (inside the grasp band 45 to 60 %).
        n_seeds (int): Random start vectors per approach bin (the home pose and the arm's current pose are always added). Defaults to 300.
        seed (int): Random seed. Defaults to 0.
        min_clear (float): The arm (fingers open) stays at least this far from the scene (not the beaker) at the solutions and along the straight moves, metres. Defaults to 5 mm.
        ready_above_top (float): The waypoint's pad centre height above the beaker's top, metres. Defaults to SEARCH_CFG["ready_clear_above_top"].
        ready_back (float): The waypoint's distance back from the beaker along the approach direction, metres. Defaults to SEARCH_CFG["ready_back_off"].

    Returns:
        dict: "grasp_q" and "ready_q" (7 joint angles, radians), "grasp_world" (the pad centre target, world), "bin", "joint_margin_deg" (of the grasp and of the ready pose, the smaller),
        "clearance_mm" (smallest distance to the scene over the grasp pose and the two straight moves) and "n_solutions" (grasp solutions that passed the clearances).

    Raises:
        RuntimeError: If no grasp solution exists or no waypoint gives clear moves.
    """
    C = grasp_cfg(model, side)
    chain, pad = arm_chain(model, side), np.array(C["pad_center_in_tcp"])
    lo, hi = joint_bounds(model, side, C)
    ids = arm_ids(model, side)
    other = "right" if side == "left" else "left"
    d = mujoco.MjData(model)
    d.qpos[:] = data.qpos
    mujoco.mj_kinematics(model, d)
    b0 = model.body("openarm_body_link0").id
    p0, R0 = d.xpos[b0].copy(), d.xmat[b0].reshape(3, 3).copy()
    to_torso = lambda w: R0.T @ (np.asarray(w, float) - p0)
    q_now = np.array([d.qpos[a] for a in ids["qadr"]])
    q_other = np.array([d.qpos[a] for a in arm_ids(model, other)["qadr"]])
    ped = float(d.qpos[model.joint(robot_specs.PEDESTAL_SPECS["joints"][0]).qposadr[0]])
    beaker = d.xpos[model.body(BEAKER_CFG["body"]).id].copy()                              # the origin is the beaker's bottom centre
    H = BEAKER_CFG["height"]
    grasp_w = beaker + [0.0, 0.0, frac * H]
    T = to_torso(grasp_w)
    sh = shoulder_origin(chain)
    az = math.atan2(T[1] - sh[1], T[0] - sh[0]) % (2 * math.pi)
    k0 = int(round(az / (2 * math.pi / C["n_bins"]))) % C["n_bins"]
    bins = [(k0 + o) % C["n_bins"] for o in (0, -1, 1, -2, 2)]

    checker = ArmCollisionChecker(model, side, q_other, finger_open=STAGING_CFG["finger_open"], pedestal_q=ped)
    world = _World(model, data, side)
    rng = np.random.default_rng(seed)

    def solve(target, k, extra_seeds):
        Q0 = np.vstack([rng.uniform(lo, hi, (n_seeds, 7)), *[np.atleast_2d(s) for s in extra_seeds]])
        Q, ok, _ = solve_ik(chain, Q0, lo, hi, make_constraint(target, k, C), pad, C["ik_max_iter"], C["ik_damping"], C["ik_max_step"])
        Q = Q[ok]
        Q = Q[~checker.check(Q)] if len(Q) else Q
        keep = [i for i, q in enumerate(Q) if world.min_distance(q) >= min_clear]
        return Q[keep]

    sols = []                                                                              # (joint margin, bin, q) of every clear grasp solution
    for k in bins:
        for q in solve(T, k, [q_now]):
            sols.append((float(_margin(model, side, q[None])[0]), k, q))
        if len(sols) >= 20:
            break
    if not sols:
        raise RuntimeError(f"no clear grasp solution for the {side} arm at the beaker {np.round(grasp_w, 3)} (bins tried {bins}, {n_seeds} random starts each)")
    sols.sort(key=lambda s: -s[0])

    ready_z = beaker[2] + H + ready_above_top                                              # the waypoint's pad centre height, world
    best = None
    for margin, k, q_g in sols[:10]:
        _, R_g = batch_fk(chain, q_g[None], pad)
        a = R_g[0] @ np.asarray(C["approach_axis"], float)
        ah = np.array([a[0], a[1], 0.0]) / max(np.hypot(a[0], a[1]), 1e-9)                # horizontal approach direction, torso frame
        T_ready = np.array([T[0], T[1], to_torso([0.0, 0.0, ready_z])[2]]) - ready_back * ah
        for q_r in solve(T_ready, k, [q_g, q_now]):
            ok1, d1 = _segment_clear(world, checker, q_now, q_r, min_clear)
            ok2, d2 = _segment_clear(world, checker, q_r, q_g, min_clear)
            if ok1 and ok2:
                cand = (float(np.abs(q_r - q_g).sum()), margin, k, q_g, q_r, min(d1, d2))
                if best is None or cand[0] < best[0]:
                    best = cand
        if best is not None:
            break
    del checker
    if best is None:
        raise RuntimeError(f"no waypoint gives clear straight moves home -> ready -> grasp for the {side} arm (grasp solutions tried: {len(sols[:10])}, clearance minimum {1000 * min_clear:.0f} mm)")
    _, margin, k, q_g, q_r, dmin = best
    return {"grasp_q": q_g, "ready_q": q_r, "grasp_world": grasp_w, "bin": int(k), "n_solutions": len(sols), "clearance_mm": 1000 * min(dmin, world.min_distance(q_g)),
            "joint_margin_deg": math.degrees(min(margin, float(_margin(model, side, q_r[None])[0])))}
